def find_common_items(list_a, list_b):
    common = []
    for item_a in list_a:
        for item_b in list_b:
            if item_a == item_b and item_a not in common:
                common.append(item_a)
    return common

print(find_common_items([1, 2, 3], [3, 4, 5]))
